// Entrée attendue (corps JSON du webhook) : { logement_id, video_url }
const corps = $("01 · Logement et vidéo").first().json.body ?? {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const logement_id = typeof corps.logement_id === 'string' ? corps.logement_id.trim() : '';
const video_url = typeof corps.video_url === 'string' ? corps.video_url.trim() : '';

const erreurs = [];
if (!UUID.test(logement_id)) erreurs.push('logement_id : UUID attendu');
if (!/^https:\/\/\S+$/.test(video_url)) erreurs.push('video_url : URL signée en https attendue');
if ('video_id' in corps || 'document_id' in corps) {
  erreurs.push('video_id et document_id ne sont plus acceptés : envoyer logement_id et video_url');
}

// Clé d'idempotence : logement + chemin de la vidéo, sans la signature de l'URL.
const cle_idempotence = 'analyse:' + logement_id + ':' + video_url.split('?')[0];

return [{ json: { valide: erreurs.length === 0, erreurs, logement_id, video_url, cle_idempotence } }];

// Sortie du nœud HTTP : { statusCode, body } ; ou { error } si le service est injoignable.
const reponse = $json;
const statut = typeof reponse.statusCode === 'number' ? reponse.statusCode : null;
const corps = reponse.body && typeof reponse.body === 'object' ? reponse.body : {};
const entree = $("02 · Contrôler l’entrée").first().json;

let cas = 'erreur';
if (statut === 200 && Array.isArray(corps.failles)) cas = 'resultat';
else if (statut === 202) cas = 'accepte';
else if (statut === 501) cas = 'stub'; // le service vision n'est encore qu'un stub

let detail = null;
if (cas === 'erreur') {
  detail = statut === null ? 'service vision injoignable' : 'réponse inattendue du service vision (HTTP ' + statut + ')';
}

return [{
  json: {
    cas,
    est_resultat: cas === 'resultat',
    est_accepte: cas === 'accepte',
    est_stub: cas === 'stub',
    statut_http: statut,
    logement_id: entree.logement_id,
    failles: cas === 'resultat' ? corps.failles : [],
    detail,
  },
}];

// Identifiant déterministe au format UUID (version 8) : rejouer le workflow réécrit les mêmes lignes.
function idDeterministe(texte) {
  let h = '';
  for (let k = 0; k < 4; k++) {
    let x = 0x811c9dc5;
    const s = k + ':' + texte;
    for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
    h += x.toString(16).padStart(8, '0');
  }
  const variante = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16);
  return h.slice(0, 8) + '-' + h.slice(8, 12) + '-8' + h.slice(13, 16) + '-' + variante + h.slice(17, 20) + '-' + h.slice(20, 32);
}

// Faille attendue du service vision :
// { risque, element, piece, cote_estimee_cm, marge_cm, gravite, priorite, position_3d }
const RISQUES = ['chute', 'intrusion', 'incendie', 'autre'];
const { logement_id, failles } = $json;
const lignes = [];
const rejetees = [];

for (const faille of failles) {
  const element = typeof faille.element === 'string' ? faille.element.trim() : '';
  if (!element) { rejetees.push({ motif: 'element manquant', faille }); continue; }
  if (!RISQUES.includes(faille.risque)) { rejetees.push({ motif: 'risque inconnu', element }); continue; }
  const piece = typeof faille.piece === 'string' ? faille.piece.trim() : '';
  lignes.push({
    id: idDeterministe([logement_id, element, piece, JSON.stringify(faille.position_3d ?? null)].join('|')),
    logement_id,
    piece_id: null, // la vision renvoie un nom de pièce ; la table pieces (issue #1) reste à relier
    risque: faille.risque,
    element,
    source: 'vision',
    cote_estimee_cm: faille.cote_estimee_cm ?? null,
    marge_cm: faille.marge_cm ?? null,
    gravite: faille.gravite ?? null,
    priorite: faille.priorite ?? null,
    position_3d: faille.position_3d ?? null,
  });
}

return [{ json: { logement_id, lignes, rejetees } }];
